export const QUIZ = [{"id": "c01q01", "ch": 1, "type": "mc", "q": "คำว่า \"มวย\" ตามคำอธิบายของกรมพลศึกษา มีความหมายว่าอะไร", "o": ["การต่อสู้", "การผูก", "การป้องกันตัว", "การร่ายรำ"], "a": 1, "exp": "กรมพลศึกษาอธิบายว่า \"มวย\" หมายถึง \"การผูก\" หรือการรวบรวมไว้ด้วยกัน สะท้อนการแต่งกายนักมวยโบราณที่มีอย่างน้อย 4 ผูก", "page": 1}, {"id": "c01q02", "ch": 1, "type": "mc", "q": "นักมวยที่ได้รับการคัดเลือกเข้ารับราชการในสมัยอยุธยาเพื่อรักษาความปลอดภัยในพระราชวัง เรียกว่าอะไร", "o": ["ทนายเลือก", "หมื่นมวยมีชื่อ", "ขุนพลมวย", "กรมนักเลง"], "a": 0, "exp": "สมัยอยุธยาคัดนักมวยฝีมือดีเข้ารับราชการเรียกว่า \"ทนายเลือก\" ทำหน้าที่รักษาความปลอดภัยในพระราชวังและเป็นครูสอนมวย", "page": 2}, {"id": "c01q03", "ch": 1, "type": "mc", "q": "พระมหากษัตริย์พระองค์ใดเคยปลอมพระองค์เป็นสามัญชนไปชกมวยที่เมืองวิเศษไชยชาญ", "o": ["สมเด็จพระนเรศวรมหาราช", "สมเด็จพระเจ้าตากสินมหาราช", "สมเด็จพระสรรเพชญ์ที่ 8 (พระเจ้าเสือ)", "พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว"], "a": 2, "exp": "พระเจ้าเสือโปรดการชกมวยมาก เคยปลอมพระองค์ไปชกที่เมืองวิเศษไชยชาญ และทรงชนะนักมวย 3 คน", "page": 2}, {"id": "c01q04", "ch": 1, "type": "mc", "q": "\"วันนักมวยไทย\" ตรงกับวันที่เท่าไร", "o": ["6 กุมภาพันธ์", "17 มีนาคม", "23 ธันวาคม", "30 กรกฎาคม"], "a": 1, "exp": "กรมพลศึกษาระบุว่าวันที่ 17 มีนาคมของทุกปีถือเป็น \"วันนักมวยไทย\" (ส่วน 6 กุมภาพันธ์ คือ \"วันมวยไทย\")", "page": 3}, {"id": "c01q05", "ch": 1, "type": "mc", "q": "\"พระยาพิชัยดาบหัก\" เดิมเป็นศิษย์ของครูมวยสำนักใด", "o": ["สำนักเขาสมอคอน", "สำนักท่าเสา (ครูเมฆ)", "สำนักไชยา", "สำนักโคราช"], "a": 1, "exp": "นายทองดี ฟันขาว เคยเป็นศิษย์ของครูเมฆแห่งสำนักท่าเสา ซึ่งเด่นด้านไม้เตะ ถีบ และศอก", "page": 3}, {"id": "c01q06", "ch": 1, "type": "mc", "q": "สนามมวยถาวรแห่งแรกที่จัดการแข่งขันเป็นประจำหลังสงครามโลกครั้งที่ 1 คือสนามใด", "o": ["สนามมวยเวทีราชดำเนิน", "สนามมวยเวทีลุมพินี", "สนามมวยสวนกุหลาบ", "สนามมวยหลักเมืองท่าช้าง"], "a": 2, "exp": "หลังสงครามโลกครั้งที่ 1 เกิดสนามมวยถาวรแห่งแรก คือ สนามมวยสวนกุหลาบ", "page": 4}, {"id": "c01q07", "ch": 1, "type": "mc", "q": "มวยไทยสายใดได้ชื่อว่า \"มวยเกี้ยว\" เพราะชกฉลาด รุกรับคล่องแคล่ว และหมัดตรงแม่นยำ", "o": ["มวยไชยา", "มวยลพบุรี", "มวยโคราช", "มวยท่าเสา"], "a": 1, "exp": "มวยลพบุรี (ภาคกลาง) ชกฉลาด รุกรับคล่องแคล่ว ต่อยหมัดตรงแม่นยำ เรียกว่า \"มวยเกี้ยว\"", "page": 5}, {"id": "c01q08", "ch": 1, "type": "mc", "q": "ท่าสำคัญของมวยไชยาที่เน้นการต่อสู้วงในด้วยศอกและเข่า คือท่าใด", "o": ["ท่าเสือลากหาง", "ท่าหมัดเหวี่ยงควาย", "ท่ามวยเกี้ยว", "ท่าพระรามแผลงศร"], "a": 0, "exp": "ท่าที่สำคัญของมวยไชยาคือท่าเสือลากหาง เน้นการต่อสู้วงในด้วยศอกและเข่า และใช้หลัก \"ป้อง ปัด ปิด เปิด\"", "page": 5}, {"id": "c01q09", "ch": 1, "type": "tf", "q": "สนามมวยเวทีราชดำเนินเปิดการแข่งขันครั้งแรกเมื่อวันที่ 23 ธันวาคม พ.ศ. 2488 โดยใช้กติกาชก 5 ยก ยกละ 3 นาที", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก เวทีราชดำเนินเปิดครั้งแรก 23 ธันวาคม พ.ศ. 2488 ใช้กติกากรมพลศึกษา พ.ศ. 2480 ชก 5 ยก ยกละ 3 นาที พัก 2 นาที", "page": 4}, {"id": "c01q10", "ch": 1, "type": "tf", "q": "ในสมัยรัชกาลที่ 1–5 มีการจับเวลายกโดยใช้กะลามะพร้าวเจาะรูลอยน้ำ เมื่อกะลาจมจึงตีกลองหมดยก", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก ตั้งแต่รัชกาลที่ 1 ถึงรัชกาลที่ 5 ใช้กะลามะพร้าวเจาะรูลอยน้ำ เมื่อกะลาจมถึงก้นอ่างจะตีกลองเป็นสัญญาณหมดยก", "page": 3}, {"id": "c02q01", "ch": 2, "type": "mc", "q": "ในสมัยก่อน ครูมวยใช้วัสดุใดแทนกระสอบทรายในการฝึก", "o": ["ต้นกล้วย", "ลูกมะพร้าวแห้ง", "กระสอบข้าวสาร", "ลูกมะนาว"], "a": 0, "exp": "ครูใช้วัสดุใกล้ตัวแทนอุปกรณ์ เช่น ลูกมะพร้าวแห้งหรือลูกมะนาวแทนเป้าล่อ และต้นกล้วยแทนกระสอบทราย", "page": 9}, {"id": "c02q02", "ch": 2, "type": "mc", "q": "พิธีขึ้นครูมักเลือกทำในวันใด เพราะถือว่าเป็นวันครู", "o": ["วันจันทร์", "วันพุธ", "วันพฤหัสบดี", "วันเสาร์"], "a": 2, "exp": "การขึ้นครูมักเลือกวันพฤหัสบดีซึ่งถือว่าเป็นวันครู", "page": 9}, {"id": "c02q03", "ch": 2, "type": "mc", "q": "ครูจะทำพิธีครอบครูให้ศิษย์เมื่อใด", "o": ["ก่อนเริ่มเรียน", "เมื่อศิษย์เรียนจบและถ่ายทอดวิชาให้ผู้อื่นได้", "ทุกปีในวันไหว้ครู", "ก่อนขึ้นชกครั้งแรก"], "a": 1, "exp": "เมื่อศิษย์ศึกษาจนหมดสิ้นและถ่ายทอดวิชาให้ผู้อื่นได้ ครูจะทำพิธีครอบครูให้", "page": 9}, {"id": "c02q04", "ch": 2, "type": "mc", "q": "เครื่องดนตรีที่บรรเลงประกอบการไหว้ครูและการชกมวยไทยประกอบด้วยอะไรบ้าง", "o": ["ปี่ชวา กลองแขก และฉิ่ง", "ปี่ใน ตะโพน และฆ้องวง", "ขลุ่ย ระนาด และฉาบ", "แคน พิณ และกลองยาว"], "a": 0, "exp": "ดนตรีประกอบมวยไทยประกอบด้วยปี่ชวา กลองแขก และฉิ่ง และบรรเลงระหว่างการชกเพื่อเร้าใจผู้ชก", "page": 9}, {"id": "c02q05", "ch": 2, "type": "mc", "q": "หน้าใหญ่ของกลองแขกเรียกว่าอะไร", "o": ["หน้าต่าน", "หน้ารุ่ย", "หน้าทับ", "หน้าเท่ง"], "a": 1, "exp": "กลองแขกหน้าใหญ่เรียกว่า \"หน้ารุ่ย\" กว้างประมาณ 20 ซม. หน้าเล็กเรียกว่า \"หน้าต่าน\"", "page": 10}, {"id": "c02q06", "ch": 2, "type": "mc", "q": "ในหลัก \"ย่างสามขุม คุมเชิงครู ดูดัสกร ฟ้อนรำเชิง\" คำว่า \"ดูดัสกร\" หมายถึงอะไร", "o": ["ยกหมัดทั้งสองตั้งให้สูง", "ตาทั้งสองต้องจ้องดูคู่ต่อสู้ตลอดเวลา", "หยั่งเชิงหลอกล่อคู่ต่อสู้", "ทิ้งน้ำหนักลงตรงกลาง"], "a": 1, "exp": "\"ดูดัสกร\" คือ ตาทั้งสองต้องจ้องดูคู่ต่อสู้ตลอดเวลา", "page": 10}, {"id": "c02q07", "ch": 2, "type": "mc", "q": "การไหว้ครูและร่ายรำแบบครูกิมเส็ง ทวีสิทธิ์ แบ่งเป็น 2 ตอน คืออะไร", "o": ["ท่าเทพพนมและท่าปฐม", "ท่าพรหมนั่งและท่าพรหมยืน", "ท่าย่างสุขเกษมและท่าย่างสามขุม", "ท่าขึ้นครูและท่าครอบครู"], "a": 1, "exp": "การไหว้ครูแบบครูกิมเส็ง ทวีสิทธิ์ แบ่งเป็น 2 ตอน คือ ท่าพรหมนั่ง และท่าพรหมยืน", "page": 11}, {"id": "c02q08", "ch": 2, "type": "mc", "q": "ท่าพรหมนั่งประกอบด้วยท่าใดบ้าง", "o": ["ท่าเทพพนม ท่าปฐม และท่าพรหม", "ท่าเทพนิมิต ท่าย่างสุขเกษม และท่าพรหม", "ท่าปั้นขนุน ท่าสอดสร้อยมาลา และท่าเทพนิมิต", "ท่าถวายบังคม ท่ากราบ และท่าย่างสามขุม"], "a": 0, "exp": "ท่าพรหมนั่งเป็นพื้นฐานของการไหว้ครู ประกอบด้วยท่าเทพพนม ท่าปฐม และท่าพรหม", "page": 11}, {"id": "c02q09", "ch": 2, "type": "tf", "q": "หากนักมวยสองฝ่ายไหว้ครูและร่ายรำแบบเดียวกัน แสดงว่าสืบสายมาจากครูเดียวกัน", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก การร่ายรำแสดงเอกลักษณ์ของครูมวยหรือค่ายมวย หากรำแบบเดียวกันย่อมแสดงว่าสืบสายมาจากครูเดียวกัน", "page": 8}, {"id": "c02q10", "ch": 2, "type": "tf", "q": "ในท่าพรหมยืน นักมวยไหว้พรหมเพียงทิศเบื้องหน้าทิศเดียว", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด ท่าพรหมยืนจะไหว้พรหมทั้งสี่ทิศ คือ ทิศเบื้องขวา ทิศเบื้องซ้าย ทิศเบื้องหลัง และทิศเบื้องหน้า", "page": 11}, {"id": "c03q01", "ch": 3, "type": "mc", "q": "นักกีฬาน้ำหนัก 45–65 กิโลกรัม ควรใช้นวมขนาดเท่าใด", "o": ["8–10 ออนซ์", "10–12 ออนซ์", "12–14 ออนซ์", "14–16 ออนซ์"], "a": 1, "exp": "ตารางการเลือกขนาดนวม น้ำหนัก 45–65 กก. ใช้นวม 10–12 ออนซ์ สำหรับแข่งขันหรือฝึกซ้อมทั่วไป", "page": 28}, {"id": "c03q02", "ch": 3, "type": "mc", "q": "ผ้าพันมือแบบดั้งเดิม (Traditional Cotton Wraps) มีความยาวประมาณเท่าใด", "o": ["2.5 เมตร", "3 เมตร", "4.5 เมตร", "8 เมตร"], "a": 2, "exp": "ผ้าพันมือแบบดั้งเดิมทำจากผ้าฝ้าย ยาวประมาณ 4.5 เมตร ต้องพันด้วยตนเองตามเทคนิคที่ถูกต้อง", "page": 28}, {"id": "c03q03", "ch": 3, "type": "mc", "q": "ที่ป้องกันฟันแบบใดที่นำไปต้มในน้ำร้อนแล้วกัดให้พอดีกับฟันของตนเอง", "o": ["แบบสำเร็จรูป (Stock)", "แบบต้มปรับรูป (Boil and Bite)", "แบบสั่งทำพิเศษ", "แบบสองชั้น"], "a": 1, "exp": "ที่ป้องกันฟันแบบต้มปรับรูปทำจากวัสดุที่อ่อนตัวเมื่อโดนความร้อน ต้มแล้วกัดให้พอดีกับฟัน", "page": 30}, {"id": "c03q04", "ch": 3, "type": "mc", "q": "แป้นชนิดใดมีขนาดใหญ่ บุนวมหนา ใช้รับแรงเตะและเข่า และขาดไม่ได้ในการฝึกมวยไทย", "o": ["แป้นชกมือ (Focus Mitts)", "แป้นเตะ (Thai Pads)", "แป้นศอก (Elbow Pads)", "กระสอบทราย"], "a": 1, "exp": "แป้นเตะมีขนาดใหญ่กว่าแป้นชกมือ บุนวมหนาเพื่อรองรับแรงเตะและเข่า", "page": 31}, {"id": "c03q05", "ch": 3, "type": "mc", "q": "ข้อใดเป็นวิธีดูแลผ้าพันมือที่ถูกต้อง", "o": ["ซักด้วยน้ำร้อนเพื่อฆ่าเชื้อ", "ตากแดดจัดให้แห้งเร็ว", "ตากในที่ร่มที่อากาศถ่ายเท", "เก็บม้วนไว้ขณะยังชื้น"], "a": 2, "exp": "ควรตากในที่ร่มที่อากาศถ่ายเท ไม่ตากแดดโดยตรง ไม่ซักน้ำร้อน และไม่เก็บขณะยังชื้น", "page": 32}, {"id": "c03q06", "ch": 3, "type": "mc", "q": "หลังใช้นวมชกมวย ควรแขวนในที่อากาศถ่ายเทอย่างน้อยกี่ชั่วโมงก่อนเก็บ", "o": ["15–30 นาที", "2–3 ชั่วโมง", "6–8 ชั่วโมง", "24 ชั่วโมง"], "a": 1, "exp": "ไม่ควรเก็บนวมในถุงพลาสติกทันที ควรแขวนในที่อากาศถ่ายเทอย่างน้อย 2–3 ชั่วโมงก่อนเก็บ", "page": 32}, {"id": "c03q07", "ch": 3, "type": "mc", "q": "ตามมาตรฐานความปลอดภัยของสถานที่ฝึกซ้อม เครื่อง AED ต้องอยู่ในตำแหน่งที่เข้าถึงได้ภายในกี่นาที", "o": ["1 นาที", "3 นาที", "10 นาที", "30 นาที"], "a": 1, "exp": "สิ่งอำนวยความสะดวกด้านความปลอดภัย: AED พร้อมใช้งานและต้องอยู่ในตำแหน่งที่เข้าถึงได้ภายใน 3 นาที", "page": 37}, {"id": "c03q08", "ch": 3, "type": "mc", "q": "เครื่องมือใดใช้ประเมินระดับความรู้สึกตัว คะแนนเต็ม 15 คะแนน", "o": ["SCAT6", "Maddocks Questions", "Glasgow Coma Scale (GCS)", "PRICE"], "a": 2, "exp": "Glasgow Coma Scale ประเมินการลืมตา การตอบสนองทางวาจา และการเคลื่อนไหว คะแนนเต็ม 15", "page": 36}, {"id": "c03q09", "ch": 3, "type": "tf", "q": "ผู้ที่สงสัยภาวะสมองกระทบกระเทือน ควรได้รับยาแก้ปวดกลุ่ม NSAIDs เช่น แอสไพริน ทันที", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด ห้ามให้ยากลุ่ม NSAIDs เพราะเพิ่มความเสี่ยงเลือดออกในสมอง", "page": 36}, {"id": "c03q10", "ch": 3, "type": "tf", "q": "อาเจียนมากกว่า 2 ครั้งหลังบาดเจ็บที่ศีรษะ เป็นอาการเตือนที่ต้องนำส่งโรงพยาบาลฉุกเฉินทันที", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก อาเจียนมากกว่า 2 ครั้งเป็นหนึ่งใน Red Flags ที่ต้องนำส่งโรงพยาบาลทันที", "page": 36}, {"id": "c04q01", "ch": 4, "type": "mc", "q": "ข้อใดเป็นองค์ประกอบของสมรรถภาพทางกายที่สัมพันธ์กับสุขภาพ", "o": ["ความเร็ว", "การทรงตัว", "องค์ประกอบของร่างกาย", "ความคล่องแคล่วว่องไว"], "a": 2, "exp": "องค์ประกอบของร่างกาย (สัดส่วนไขมันและส่วนที่ไม่ใช่ไขมัน) จัดอยู่ในกลุ่มที่สัมพันธ์กับสุขภาพ ตามตารางที่ 4.1", "page": 40}, {"id": "c04q02", "ch": 4, "type": "mc", "q": "\"ความสามารถในการเปลี่ยนทิศทางได้อย่างรวดเร็ว\" คือองค์ประกอบใด", "o": ["ความเร็ว", "ความคล่องแคล่วว่องไว", "กำลังของกล้ามเนื้อ", "การทำงานที่ประสานกัน"], "a": 1, "exp": "ความคล่องแคล่วว่องไว คือความสามารถในการเปลี่ยนทิศทางได้อย่างรวดเร็ว", "page": 40}, {"id": "c04q03", "ch": 4, "type": "mc", "q": "ข้อใดเป็นปัจจัยภายนอกที่มีอิทธิพลต่อสมรรถภาพทางกาย", "o": ["อายุ", "เพศ", "พันธุกรรม", "การฝึกซ้อม"], "a": 3, "exp": "ปัจจัยภายใน ได้แก่ อายุ เพศ สภาพร่างกาย พันธุกรรม ส่วนปัจจัยภายนอก เช่น การฝึกซ้อมและโภชนาการ", "page": 40}, {"id": "c04q04", "ch": 4, "type": "mc", "q": "การฝึกต้องสอดคล้องกับระบบพลังงาน ลักษณะการเคลื่อนไหว และกลุ่มกล้ามเนื้อที่ใช้ในมวยไทย เป็นหลักการใด", "o": ["หลักการฝึกเฉพาะเจาะจง", "หลักการย้อนกลับ", "หลักการฟื้นสภาพร่างกาย", "หลักการใช้ความหนักมากกว่าปกติ"], "a": 0, "exp": "หลักการฝึกเฉพาะเจาะจง (Principle of Specificity) คือการฝึกให้สอดคล้องกับระบบพลังงานและการเคลื่อนไหวของมวยไทย", "page": 41}, {"id": "c04q05", "ch": 4, "type": "mc", "q": "การชกตลอดยกและการฟื้นตัวระหว่างยกอาศัยระบบพลังงานใดเป็นหลัก", "o": ["แอนแอโรบิก อแล็กเทส", "แอนแอโรบิก แล็กเทส", "แอโรบิก", "ระบบ ATP-CP"], "a": 2, "exp": "ระบบแอโรบิกใช้ออกซิเจน ให้พลังงานต่อเนื่องได้นาน เช่น การชกตลอดยกและการฟื้นตัวระหว่างยก", "page": 42}, {"id": "c04q06", "ch": 4, "type": "mc", "q": "การพัฒนาพลังกล้ามเนื้อด้วยการกระโดดในแนวราบและแนวดิ่ง เรียกว่าการฝึกแบบใด", "o": ["การฝึกแบบวงจร", "การฝึกพลัยโอเมตริก", "การยืดเหยียดแบบอยู่กับที่", "การฝึกแบบหนักสลับเบา"], "a": 1, "exp": "การพัฒนาพลังทำได้ด้วยการฝึกพลัยโอเมตริก ซึ่งใช้การกระโดดในแนวราบและแนวดิ่ง", "page": 42}, {"id": "c04q07", "ch": 4, "type": "mc", "q": "ขั้นตอนการฝึกความอ่อนตัวที่ถูกต้องคือข้อใด", "o": ["ยืดเหยียด → อบอุ่นร่างกาย → คลายอุ่น", "อบอุ่นร่างกาย → ยืดเหยียด → คลายอุ่น", "คลายอุ่น → ยืดเหยียด → อบอุ่นร่างกาย", "ยืดเหยียด → คลายอุ่น → อบอุ่นร่างกาย"], "a": 1, "exp": "ขั้นตอนการฝึกความอ่อนตัวเริ่มจากการอบอุ่นร่างกาย ตามด้วยการยืดเหยียด และจบด้วยการคลายอุ่น", "page": 42}, {"id": "c04q08", "ch": 4, "type": "mc", "q": "ระบบพลังงานแอนแอโรบิก แล็กเทส (Glycolysis) เด่นในช่วงเวลาประมาณเท่าใด", "o": ["1–3 วินาที", "20–45 วินาทีถึง 2 นาที", "5–10 นาที", "มากกว่า 30 นาที"], "a": 1, "exp": "ระบบแอนแอโรบิก แล็กเทส ใช้ไกลโคเจน เกิดกรดแล็กติก เด่นในช่วงประมาณ 20–45 วินาทีถึง 2 นาที", "page": 41}, {"id": "c04q09", "ch": 4, "type": "tf", "q": "ร่างกายต้องได้รับการฟื้นสภาพหลังการฝึกหนัก เช่น การพักอย่างมีกิจกรรมและการนอนหลับ เป็นหลักการฟื้นสภาพร่างกาย", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก หลักการฟื้นสภาพร่างกาย (Principle of Recuperation) เช่น การพักอย่างมีกิจกรรมด้วยความหนักต่ำ และการพักอย่างสมบูรณ์โดยเฉพาะการนอนหลับ", "page": 41}, {"id": "c04q10", "ch": 4, "type": "tf", "q": "การฝึกมวยไทยต้องอาศัยความว่องไว จึงต้องอบอุ่นร่างกายทุกครั้งก่อนฝึก", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก กรมพลศึกษาระบุว่าการฝึกมวยไทยต้องอาศัยความว่องไว การหลบหลีก และการหลอกล่อ จึงต้องอบอุ่นร่างกายทุกครั้ง", "page": 42}, {"id": "c05q01", "ch": 5, "type": "mc", "q": "ผ้าพันมือสำหรับการแข่งขันควรมีความยาวเท่าใด", "o": ["2–3 เมตร", "3–4 เมตร", "4.5–6 เมตร", "7–8 เมตร"], "a": 2, "exp": "ตารางอุปกรณ์ที่ต้องเตรียม: ฝึกซ้อมทั่วไป 4–5 เมตร แข่งขัน 4.5–6 เมตร", "page": 45}, {"id": "c05q02", "ch": 5, "type": "mc", "q": "การพันมือแบบมาตรฐานสำหรับมวยไทยมีทั้งหมดกี่ขั้นตอน", "o": ["6 ขั้นตอน", "8 ขั้นตอน", "10 ขั้นตอน", "12 ขั้นตอน"], "a": 2, "exp": "การพันมือแบบมาตรฐานสำหรับมวยไทยมีทั้งหมด 10 ขั้นตอน", "page": 46}, {"id": "c05q03", "ch": 5, "type": "mc", "q": "การพันระหว่างนิ้ว (Cross Wrap) ควรเริ่มจากช่องนิ้วใด", "o": ["นิ้วหัวแม่มือกับนิ้วชี้", "นิ้วชี้กับนิ้วกลาง", "นิ้วกลางกับนิ้วนาง", "นิ้วก้อยกับนิ้วนาง"], "a": 3, "exp": "นำผ้าพันผ่านระหว่างนิ้วมือแต่ละนิ้ว โดยเริ่มจากระหว่างนิ้วก้อยและนิ้วนาง", "page": 46}, {"id": "c05q04", "ch": 5, "type": "mc", "q": "ในท่าจดมวย ควรวางข้อศอกอย่างไร", "o": ["กางศอกออกให้กว้าง", "ลดข้อศอกลงเพื่อป้องกันซี่โครง", "ยกศอกสูงระดับหู", "เหยียดแขนตรงไปข้างหน้า"], "a": 1, "exp": "ลดข้อศอกลงเพื่อป้องกันซี่โครง โดยเฉพาะในมวยไทยที่มีการโจมตีด้วยเข่าและเตะบริเวณลำตัว", "page": 48}, {"id": "c05q05", "ch": 5, "type": "mc", "q": "ในท่าจดมวย ควรหันลำตัวเฉียงประมาณกี่องศา", "o": ["10–15 องศา", "30–45 องศา", "60–75 องศา", "90 องศา"], "a": 1, "exp": "หันลำตัวเฉียงประมาณ 30–45 องศา ให้ด้านข้างหันเข้าหาคู่ต่อสู้เพื่อลดพื้นที่เป้าหมาย", "page": 48}, {"id": "c05q06", "ch": 5, "type": "mc", "q": "ในท่าจดมวย การลงน้ำหนักบนเท้าทั้งสองควรเป็นสัดส่วนเท่าใด", "o": ["50:50 หรือเอนมาด้านหน้าเล็กน้อย", "80:20 ลงเท้าหน้า", "20:80 ลงเท้าหลัง", "100% ที่เท้าหลัง"], "a": 0, "exp": "กระจายน้ำหนักบนปลายเท้าทั้งสองข้าง 50:50 หรือเอนมาด้านหน้าเล็กน้อย", "page": 47}, {"id": "c05q07", "ch": 5, "type": "mc", "q": "ในท่าจดมวย สายตาควรมองไปที่ตำแหน่งใดของคู่ต่อสู้", "o": ["มือของคู่ต่อสู้", "เท้าของคู่ต่อสู้", "ระดับอก-ไหล่", "พื้นเวที"], "a": 2, "exp": "สายตามองตรงไปยังคู่ต่อสู้ในระดับอก-ไหล่ ไม่จ้องที่มือหรือเท้า เพื่อมองได้มุมกว้าง", "page": 48}, {"id": "c05q08", "ch": 5, "type": "mc", "q": "การก้าวเท้าหลังไปข้างหน้าเพื่อเปลี่ยนการ์ด คือการเคลื่อนที่แบบใด", "o": ["การรุกเท้าตาม", "การรุกเท้าสลับ", "การถอยเท้าตาม", "การฉาก"], "a": 1, "exp": "การรุกเท้าสลับ คือก้าวเท้าหลังไปข้างหน้า (การเปลี่ยนการ์ด) และคงลักษณะการ์ด", "page": 50}, {"id": "c05q09", "ch": 5, "type": "tf", "q": "ในมวยไทยดั้งเดิม การวางมือจะต่ำกว่ามวยสากล", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด การวางมือในมวยไทยดั้งเดิมจะสูงกว่ามวยสากล เพราะต้องป้องกันศอกและเข่าที่มาในมุมสูง", "page": 48}, {"id": "c05q10", "ch": 5, "type": "tf", "q": "ก่อนพันมือควรล้างมือให้สะอาดและเช็ดให้แห้งสนิท", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก เพื่อป้องกันการสะสมของเชื้อโรคและกลิ่นอับในผ้าพันมือ", "page": 46}, {"id": "c06q01", "ch": 6, "type": "mc", "q": "หมัดใดมีวิถีเป็นแนวทแยงจากล่างขึ้นบน คล้ายการเสยหรือตักขึ้น", "o": ["หมัดตรง", "หมัดเหวี่ยง", "หมัดเสย", "หมัดสอย"], "a": 2, "exp": "หมัดเสยมีลักษณะการเคลื่อนที่เป็นแนวทแยงจากล่างขึ้นบน คล้ายการเสยหรือตักขึ้น", "page": 56}, {"id": "c06q02", "ch": 6, "type": "mc", "q": "หมัดเหวี่ยงกลับหลัง (Spinning Backfist) สร้างพลังจากอะไร", "o": ["การกระโดดขึ้น", "แรงเหวี่ยงจากการหมุนตัวกลับไปด้านหลัง", "การบิดข้อมือ", "การดันจากเท้าหน้า"], "a": 1, "exp": "หมัดเหวี่ยงกลับหลังใช้แรงเหวี่ยงจากการหมุนตัวกลับไปด้านหลังเพื่อสร้างพลังกระแทก", "page": 58}, {"id": "c06q03", "ch": 6, "type": "mc", "q": "การถีบที่ใช้บ่อยที่สุดและเป็นพื้นฐานของการถีบทั้งหมดคือข้อใด", "o": ["ถีบตรง", "ถีบข้าง", "ถีบเฉียง", "ถีบกระโดด"], "a": 0, "exp": "ถีบตรง (ถีบหน้า) เป็นการถีบที่ใช้บ่อยที่สุดและเป็นพื้นฐานของการถีบทั้งหมด", "page": 59}, {"id": "c06q04", "ch": 6, "type": "mc", "q": "การถีบแบบใดที่หันด้านข้างของร่างกายเข้าหาคู่ต่อสู้แล้วถีบออกไปด้านข้าง", "o": ["ถีบตรง", "ถีบข้าง", "ถีบกลับ", "ถีบกระโดด"], "a": 1, "exp": "ถีบข้าง (ถีบไซด์) เป็นการถีบในแนวข้าง โดยหันด้านข้างของร่างกายเข้าหาคู่ต่อสู้", "page": 60}, {"id": "c06q05", "ch": 6, "type": "mc", "q": "ถีบเฉียง (ถีบทแยง) เป็นการผสมผสานระหว่างการถีบแบบใด", "o": ["ถีบตรงและถีบข้าง", "ถีบกลับและถีบกระโดด", "ถีบตรงและเตะตัด", "ถีบข้างและเตะกลับ"], "a": 0, "exp": "ถีบเฉียงเป็นการถีบในแนวทแยงมุม การเคลื่อนไหวผสมผสานระหว่างถีบตรงและถีบข้าง", "page": 60}, {"id": "c06q06", "ch": 6, "type": "mc", "q": "เตะตรง (เตะตึง) มุ่งโจมตีบริเวณใด", "o": ["ข้อพับเข่า", "ลำตัว หน้าอก หน้าท้อง หรือใบหน้า", "น่องด้านหลัง", "ข้อเท้า"], "a": 1, "exp": "เตะตรงเตะในแนวตรง มุ่งโจมตีลำตัว หน้าอก หน้าท้อง หรือใบหน้า", "page": 60}, {"id": "c06q07", "ch": 6, "type": "mc", "q": "การเตะใดเข้าบริเวณซี่โครง หน้าท้อง หรือหน้าอก ทำให้หายใจลำบาก", "o": ["เตะเฉียง", "เตะตรง", "เตะกลับ", "เตะกระโดด"], "a": 0, "exp": "เตะเฉียงเป็นการเตะเข้าบริเวณลำตัว โดยเฉพาะซี่โครง หน้าท้อง หรือหน้าอก ทำให้หายใจลำบาก", "page": 64}, {"id": "c06q08", "ch": 6, "type": "mc", "q": "เตะกลับ (เตะหมุนกลับ) ต้องหมุนตัวกลับหลังประมาณกี่องศา", "o": ["45–90 องศา", "90–120 องศา", "180–360 องศา", "720 องศา"], "a": 2, "exp": "เตะกลับเป็นการหมุนตัวกลับหลัง 180–360 องศา แล้วเตะด้วยส้นเท้าหรือหลังส้นเท้า", "page": 54}, {"id": "c06q09", "ch": 6, "type": "tf", "q": "เตะกระโดดมีพลังสูงแต่มีความเสี่ยงสูง เพราะขณะอยู่ในอากาศไม่สามารถเปลี่ยนทิศทางได้", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก เตะกระโดดได้แรงจากการกระโดด น้ำหนักตัว และแรงโน้มถ่วง แต่ขณะลอยตัวไม่สามารถเปลี่ยนทิศทางได้", "page": 62}, {"id": "c06q10", "ch": 6, "type": "tf", "q": "ถีบกลับคล้ายเตะกลับ แต่เน้นการถีบผลักมากกว่าการฟาด", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก ถีบกลับหมุนตัวกลับหลังแล้วถีบด้วยส้นเท้า คล้ายเตะกลับแต่เน้นการถีบผลักมากกว่าการฟาด", "page": 61}, {"id": "c07q01", "ch": 7, "type": "mc", "q": "เข่าใดเป็นเข่าพื้นฐานที่สำคัญที่สุดและเป็นรากฐานของเข่าทุกประเภท", "o": ["เข่าตรง", "เข่าเฉียง", "เข่าโค้ง", "เข่าลอย"], "a": 0, "exp": "เข่าตรง (เข่าตึง) เป็นเข่าพื้นฐานที่สำคัญที่สุด ยกเข่าขึ้นในแนวตรงตั้งฉากกับพื้น", "page": 67}, {"id": "c07q02", "ch": 7, "type": "mc", "q": "เข่าเฉียงยกขึ้นในแนวทแยงมุม เอียงไปด้านข้างประมาณกี่องศา", "o": ["15 องศา", "30 องศา", "45 องศา", "90 องศา"], "a": 2, "exp": "เข่าเฉียง (เข่าทแยง) ยกเข่าในแนวทแยง เอียงไปด้านข้างประมาณ 45 องศา", "page": 68}, {"id": "c07q03", "ch": 7, "type": "mc", "q": "เข่าโค้งมีชื่อเรียกอีกอย่างหนึ่งว่าอะไร", "o": ["เข่าตึง", "เข่าเหลื่อมหรือเข่าตัด", "เข่าเหาะ", "เข่างัด"], "a": 1, "exp": "เข่าโค้ง หรือเข่าเหลื่อม หรือเข่าตัด เป็นการใช้เข่าฟาดในแนวโค้งหรือแนวข้าง คล้ายเตะตัดแต่ใช้เข่า", "page": 69}, {"id": "c07q04", "ch": 7, "type": "mc", "q": "ศอกพื้นฐานที่ใช้บ่อยที่สุด ฟาดไปข้างหน้าในแนวตรงหรือแนวทแยง คือศอกใด", "o": ["ศอกตี (ศอกตรง)", "ศอกงัด", "ศอกกลับ", "ศอกกระโดด"], "a": 0, "exp": "ศอกตี (ศอกตรง) ฟาดไปข้างหน้าในแนวตรงหรือแนวทแยง เป็นศอกพื้นฐานที่ใช้บ่อยที่สุด", "page": 71}, {"id": "c07q05", "ch": 7, "type": "mc", "q": "ศอกแนวนอน (ศอกตัด) มักโจมตีบริเวณใด", "o": ["ใต้คาง", "ขมับ แก้ม หรือด้านข้างของศีรษะ", "หน้าท้อง", "หน้าแข้ง"], "a": 1, "exp": "ศอกแนวนอนฟาดในแนวนอนเข้าด้านข้างของศีรษะหรือลำตัว มักโจมตีขมับ แก้ม หรือด้านข้าง", "page": 71}, {"id": "c07q06", "ch": 7, "type": "mc", "q": "จุดกระแทกหลักของศอกสับคือส่วนใด", "o": ["ปลายแขน", "สันศอกด้านนอก", "ข้อมือ", "ต้นแขนด้านใน"], "a": 1, "exp": "ศอกสับฟาดลงในแนวทแยงจากบนลงล่าง จุดกระแทกหลักคือสันศอกด้านนอก ซึ่งแข็งและคมที่สุดของแขน", "page": 72}, {"id": "c07q07", "ch": 7, "type": "mc", "q": "ศอกใดใช้การหมุนตัวกลับหลังแล้วเหวี่ยงศอกไปโจมตี คล้ายหมัดเหวี่ยงกลับหลังแต่ใช้ศอกแทน", "o": ["ศอกงัด", "ศอกกลับ", "ศอกตี", "ศอกสับ"], "a": 1, "exp": "ศอกกลับ (ศอกเหวี่ยงกลับ/ศอกหมุน) หมุนตัวกลับหลังแล้วเหวี่ยงศอกไปโจมตี", "page": 73}, {"id": "c07q08", "ch": 7, "type": "mc", "q": "ศอกงัดมีชื่อเรียกอีกอย่างหนึ่งว่าอะไร", "o": ["ศอกตรง", "ศอกแนวนอน", "ศอกเสย / ศอกอัปเปอร์คัต", "ศอกหมุน"], "a": 2, "exp": "ศอกงัด หรือศอกเสย/ศอกอัปเปอร์คัต เป็นการงัดศอกขึ้นจากล่างขึ้นบน", "page": 72}, {"id": "c07q09", "ch": 7, "type": "tf", "q": "ศอกกระโดด (ศอกบิน) มีพลังสูงเพราะได้แรงจากน้ำหนักตัวและแรงโน้มถ่วง", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก ศอกกระโดดได้แรงจากน้ำหนักตัวและแรงโน้มถ่วง เป็นท่าที่ตื่นตาและมีพลังสูงมาก", "page": 74}, {"id": "c07q10", "ch": 7, "type": "tf", "q": "เข่าและศอกเป็นอาวุธระยะไกลของมวยไทย", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด เข่าและศอกเป็นอาวุธระยะใกล้ (ระยะประชิดหรือวงใน) ตามตารางระยะการชก (บทที่ 8)", "page": 76}, {"id": "c08q01", "ch": 8, "type": "mc", "q": "ระยะกลางในการชกมวยไทยเหมาะกับอาวุธใด", "o": ["เท้า", "หมัด", "ศอก", "เข่า"], "a": 1, "exp": "ระยะกลางเหมาะกับหมัด ใช้เปิดเกมรุก หลอกล่อ และต่อเนื่องไปสู่อาวุธอื่น", "page": 76}, {"id": "c08q02", "ch": 8, "type": "mc", "q": "การออกอาวุธก่อนที่อาวุธของคู่ต่อสู้จะถึงตัว เรียกว่าจังหวะใด", "o": ["จังหวะชิงชก", "จังหวะโต้ตอบ", "จังหวะสวน", "จังหวะตาม"], "a": 0, "exp": "จังหวะชิงชก (ชิงทำก่อน) คือการออกอาวุธก่อนที่อาวุธของคู่ต่อสู้จะถึงตัว", "page": 76}, {"id": "c08q03", "ch": 8, "type": "mc", "q": "การออกอาวุธพร้อมกับที่คู่ต่อสู้ออกอาวุธ ทำให้แรงปะทะเพิ่มขึ้นแต่เสี่ยงโดนทั้งคู่ คือจังหวะใด", "o": ["จังหวะชิงชก", "จังหวะโต้ตอบ", "จังหวะสวน", "จังหวะตาม"], "a": 2, "exp": "จังหวะสวน คือการออกอาวุธสวนในขณะเดียวกับที่คู่ต่อสู้ออกอาวุธ", "page": 76}, {"id": "c08q04", "ch": 8, "type": "mc", "q": "การรุกต่อเนื่องทันทีเมื่อคู่ต่อสู้เสียหลักหรือเสียเปรียบ คือจังหวะใด", "o": ["จังหวะชิงชก", "จังหวะโต้ตอบ", "จังหวะสวน", "จังหวะตาม"], "a": 3, "exp": "จังหวะตาม (จังหวะตามทำ) คือการรุกต่อเนื่องทันทีเมื่อคู่ต่อสู้เสียหลัก", "page": 77}, {"id": "c08q05", "ch": 8, "type": "mc", "q": "หลักการป้องกันใดถือว่าดีที่สุด หากตัดสินใจและเลือกจังหวะได้ถูกต้อง", "o": ["การชิงทำก่อน", "การหลบหลีก", "การรับหรือการปิด", "การรักษาระยะ"], "a": 0, "exp": "การชิงทำก่อนถือเป็นการป้องกันที่ดีที่สุด หากตัดสินใจและเลือกจังหวะได้ถูกต้อง", "page": 77}, {"id": "c08q06", "ch": 8, "type": "mc", "q": "คำคล้องจอง \"เขาหย่อนเราตอบ\" หมายถึงหลักการใด", "o": ["การหลบหลีก", "การโต้ตอบตามจังหวะ", "การฉวยโอกาสซ้ำเติม", "การใช้โอกาสที่ได้เปรียบ"], "a": 1, "exp": "\"เขาหย่อนเราตอบ\" หมายถึงการโต้ตอบตามจังหวะ", "page": 78}, {"id": "c08q07", "ch": 8, "type": "mc", "q": "ข้อใดเป็นการตอบโต้แบบ \"รับแล้วตอบ\" ที่ถูกต้องตามเอกสาร", "o": ["ยกแข้งรับการเตะ แล้วตอบด้วยเตะเฉียงข้างเดียวกัน", "ถอยหนีจนชิดเชือก", "หันหลังให้คู่ต่อสู้", "ยืนรับหมัดโดยไม่ป้องกัน"], "a": 0, "exp": "ตัวอย่าง \"รับแล้วตอบ\" เช่น ยกแข้งรับการเตะ แล้วตอบด้วยเตะเฉียงข้างเดียวกัน", "page": 79}, {"id": "c08q08", "ch": 8, "type": "mc", "q": "ตามตารางการป้องกันอาวุธแต่ละชนิด การรับมือกับมวยถนัดซ้ายควรทำอย่างไร", "o": ["เข้าวงในทันทีทุกครั้ง", "หลบไปทางด้านที่คู่ต่อสู้ไม่ถนัด และจดมวยให้สอดคล้อง", "ยืนนิ่งรอรับการโจมตี", "เปลี่ยนไปใช้เฉพาะการถีบ"], "a": 1, "exp": "มวยถนัดซ้าย: หลบไปทางด้านที่คู่ต่อสู้ไม่ถนัด และจดมวยให้สอดคล้อง", "page": 78}, {"id": "c08q09", "ch": 8, "type": "tf", "q": "ในการฝึกคู่ของผู้เริ่มต้น ควรงดการใช้ศอกและเข่าเข้าศีรษะ", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก เป็นข้อปฏิบัติด้านความปลอดภัยในการฝึกรุก-รับ", "page": 80}, {"id": "c08q10", "ch": 8, "type": "tf", "q": "หากคู่ต่อสู้ถนัดศอก ควรเข้าระยะใกล้ให้มากที่สุด", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด หลักการรักษาระยะคือจัดระยะไม่ให้คู่ต่อสู้ใช้อาวุธที่ถนัด หากคู่ต่อสู้ถนัดศอกควรหลีกเลี่ยงระยะใกล้", "page": 77}, {"id": "c09q01", "ch": 9, "type": "mc", "q": "แม่ไม้ที่ 1 \"สลับฟันปลา\" มีลักษณะท่าอย่างไร", "o": ["รับวงนอก ท่าคล้ายทำลายหัวไหล่แขนวงนอก", "รับวงใน ท่าคล้ายทำลายหัวไหล่แขนวงใน", "ศอกวงนอก", "รับเตะด้วยศอก"], "a": 0, "exp": "สลับฟันปลา: รับวงนอก ท่าคล้ายทำลายหัวไหล่แขนวงนอก", "page": 83}, {"id": "c09q02", "ch": 9, "type": "mc", "q": "แม่ไม้ใดมีลักษณะ \"ศอกวงใน ท่าคล้ายทำลายหัวไหล่แขนวงใน\"", "o": ["ชวาซัดหอก", "อิเหนาแทงกริช", "ปักษาแหวกรัง", "ยอเขาพระสุเมรุ"], "a": 1, "exp": "อิเหนาแทงกริช: ศอกวงใน ท่าคล้ายทำลายหัวไหล่แขนวงใน", "page": 86}, {"id": "c09q03", "ch": 9, "type": "mc", "q": "แม่ไม้ \"จระเข้ฟาดหาง\" มีลักษณะท่าอย่างไร", "o": ["รับต่อยด้วยถีบ", "รับต่อยด้วยเตะ", "รับเตะด้วยถีบ", "ถองโคนขา"], "a": 1, "exp": "จระเข้ฟาดหาง: รับต่อยด้วยเตะ ท่าคล้ายทำลายใบหน้าฝ่ายรุก", "page": 91}, {"id": "c09q04", "ch": 9, "type": "mc", "q": "แม่ไม้ใดมีลักษณะ \"บิดขาจับตีเข่าที่น่อง\"", "o": ["หักงวงไอยรา", "นาคาบิดหาง", "วิรุฬหกกลับ", "หักคอเอราวัณ"], "a": 1, "exp": "นาคาบิดหาง: บิดขาจับตีเข่าที่น่อง ท่าคล้ายทำลายน่องฝ่ายรุก", "page": 93}, {"id": "c09q05", "ch": 9, "type": "mc", "q": "แม่ไม้ลำดับสุดท้าย (ไม้ที่ 15) คือข้อใด", "o": ["ขุนยักษ์จับลิง", "ดับชวาลา", "หักคอเอราวัณ", "วิรุฬหกกลับ"], "a": 2, "exp": "แม่ไม้ที่ 15 คือหักคอเอราวัณ ลักษณะท่าโน้มคอตีเข่า", "page": 97}, {"id": "c09q06", "ch": 9, "type": "mc", "q": "แม่ไม้ \"ยอเขาพระสุเมรุ\" ฝ่ายรับก้มตัวประมาณกี่องศา", "o": ["15 องศา", "30 องศา", "45 องศา", "90 องศา"], "a": 1, "exp": "ยอเขาพระสุเมรุ: ต่อยตั้งหมัดต่ำ ก้มตัว 30 องศา ท่าคล้ายทำลายคางฝ่ายรุก", "page": 87}, {"id": "c09q07", "ch": 9, "type": "mc", "q": "แม่ไม้ \"ปักลูกทอย\" มีลักษณะท่าอย่างไร", "o": ["รับเตะด้วยศอก", "รับเตะด้วยถีบ", "ถองโคนขา", "ต่อยคางหมัดสูง"], "a": 0, "exp": "ปักลูกทอย: รับเตะด้วยศอก ท่าคล้ายทำลายโคนขาฝ่ายรุก", "page": 90}, {"id": "c09q08", "ch": 9, "type": "mc", "q": "ตามตารางเอกลักษณ์ของมวยไทย \"ศิลปะแห่งแปดอาวุธ\" การกอดรัด (Chap Kho) ใช้อวัยวะใด", "o": ["กำปั้นทั้งสองข้าง", "เท้าและหน้าแข้ง", "ลำตัวและแขน", "ศอกทั้งสองข้าง"], "a": 2, "exp": "ตารางเอกลักษณ์ของมวยไทยระบุว่าการกอดรัด (Chap Kho) ใช้ลำตัวและแขน เช่น คลินช์ ดึงคอ ล็อคคอ", "page": 81}, {"id": "c09q09", "ch": 9, "type": "tf", "q": "สื่อวิดีโอสั้นบนแพลตฟอร์มติ๊กต็อก (TikTok) เรื่องการฝึกทักษะแม่ไม้มวยไทย มีประสิทธิภาพตามเกณฑ์มาตรฐาน 80/80", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก ยงยุทธ ลาดนอก และชารีรัตน์ อุดมวิโรจน์สิน พัฒนาสื่อวิดีโอสั้นที่มีประสิทธิภาพตามเกณฑ์ 80/80 (E1/E2)", "page": 98}, {"id": "c09q10", "ch": 9, "type": "tf", "q": "การฝึกแม่ไม้ควรฝึกเฉพาะฝ่ายรุกเท่านั้น", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด ต้องฝึกทั้งฝ่ายรุกและฝ่ายรับ เพื่อความสมบูรณ์ของทักษะ", "page": 83}, {"id": "c10q01", "ch": 10, "type": "mc", "q": "ลูกไม้ที่ 2 คือข้อใด", "o": ["เอราวัณเสยงา", "บาทาลูบพักตร์", "ขุนยักษ์พานาง", "พระรามน้าวศร"], "a": 1, "exp": "ลูกไม้ที่ 2 บาทาลูบพักตร์ ท่าคล้ายทำลายบริเวณใบหน้าฝ่ายรุก", "page": 102}, {"id": "c10q02", "ch": 10, "type": "mc", "q": "ลูกไม้ \"ขุนยักษ์พานาง\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["ใต้คาง", "หลังและลำตัว", "โคนขาซ้าย", "หน้าอก"], "a": 1, "exp": "ขุนยักษ์พานาง: ท่าคล้ายทำลายบริเวณหลังและลำตัวฝ่ายรุก", "page": 103}, {"id": "c10q03", "ch": 10, "type": "mc", "q": "ลูกไม้ \"ไกรสรข้ามห้วย\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["โคนขาขวา", "ใบหน้า", "หัวไหล่ด้านใน", "คาง"], "a": 0, "exp": "ไกรสรข้ามห้วย: ท่าคล้ายทำลายโคนขาขวาฝ่ายรุก", "page": 105}, {"id": "c10q04", "ch": 10, "type": "mc", "q": "ลูกไม้ \"หงส์ปีกหัก\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["หน้าอก", "หัวไหล่ด้านใน", "ขาหรือเท้า", "ด้านหลัง"], "a": 1, "exp": "หงส์ปีกหัก: ท่าคล้ายทำลายหัวไหล่ด้านในฝ่ายรุก", "page": 112}, {"id": "c10q05", "ch": 10, "type": "mc", "q": "ลูกไม้ \"สักพวงมาลัย\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["หน้าอก", "ใต้คาง", "โคนขาซ้าย", "ใบหน้า"], "a": 0, "exp": "สักพวงมาลัย: ท่าคล้ายทำลายหน้าอกฝ่ายรุก", "page": 113}, {"id": "c10q06", "ch": 10, "type": "mc", "q": "ลูกไม้ลำดับสุดท้าย (ไม้ที่ 15) คือข้อใด", "o": ["เถรกวาดลาน", "ฝานลูกบวบ", "ทะแยค้ำเสา", "ญวนทอดแห"], "a": 1, "exp": "ลูกไม้ที่ 15 คือฝานลูกบวบ ท่าคล้ายทำลายใบหน้าฝ่ายรุก", "page": 115}, {"id": "c10q07", "ch": 10, "type": "mc", "q": "ลูกไม้ \"ญวนทอดแห\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["หน้าอก", "หัวไหล่ด้านใน", "ด้านหลังหรือโคนขาซ้าย", "ใบหน้า"], "a": 2, "exp": "ญวนทอดแห: ท่าคล้ายทำลายบริเวณด้านหลังหรือโคนขาซ้ายฝ่ายรุก", "page": 110}, {"id": "c10q08", "ch": 10, "type": "mc", "q": "ลูกไม้ \"พระรามน้าวศร\" มีลักษณะท่าคล้ายทำลายบริเวณใด", "o": ["ลำตัว", "หัวไหล่ด้านใน", "หน้าอก", "โคนขาขวา"], "a": 0, "exp": "พระรามน้าวศร: ท่าคล้ายทำลายบริเวณลำตัวฝ่ายรุก", "page": 104}, {"id": "c10q09", "ch": 10, "type": "tf", "q": "ลูกไม้ \"นาคมุดบาดาล\" มีลักษณะท่าคล้ายทำลายโคนขาซ้ายฝ่ายรุก", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก นาคมุดบาดาล: ท่าคล้ายทำลายโคนขาซ้ายฝ่ายรุก", "page": 108}, {"id": "c10q10", "ch": 10, "type": "tf", "q": "ลูกไม้มวยไทยมีจำนวน 25 ไม้", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด ลูกไม้มวยไทยมี 15 ไม้ เท่ากับแม่ไม้", "page": 100}, {"id": "c11q01", "ch": 11, "type": "mc", "q": "เชือกกั้นเวทีมวยไทยมีกี่เส้น", "o": ["2 เส้น", "3 เส้น", "4 เส้น", "5 เส้น"], "a": 2, "exp": "เชือกกั้นเวทีมี 4 เส้น หุ้มด้วยวัสดุอ่อนนุ่ม สูงจากพื้นเวที 45, 75, 105 และ 135 เซนติเมตร", "page": 117}, {"id": "c11q02", "ch": 11, "type": "mc", "q": "มุมแดงของเวทีอยู่ตำแหน่งใด", "o": ["ทางขวามือของโต๊ะประธานผู้ตัดสิน", "ทางซ้ายมือของโต๊ะประธานผู้ตัดสิน", "ตรงข้ามผู้ชม", "ด้านหลังผู้จับเวลา"], "a": 1, "exp": "มุมแดงอยู่ทางซ้ายมือของโต๊ะประธานผู้ตัดสิน มุมน้ำเงินอยู่ตรงข้าม", "page": 117}, {"id": "c11q03", "ch": 11, "type": "mc", "q": "นักมวยรุ่นซูเปอร์เวลเตอร์เวทขึ้นไป ใช้นวมขนาดเท่าใด", "o": ["6 ออนซ์", "8 ออนซ์", "10 ออนซ์", "12 ออนซ์"], "a": 2, "exp": "ตารางนวม: มินิฟลายเวทถึงเฟเธอร์เวท 6 ออนซ์ ซูเปอร์เฟเธอร์เวทถึงเวลเตอร์เวท 8 ออนซ์ ซูเปอร์เวลเตอร์เวทขึ้นไป 10 ออนซ์", "page": 118}, {"id": "c11q04", "ch": 11, "type": "mc", "q": "รุ่นไลต์เวทมีพิกัดน้ำหนักตามข้อใด", "o": ["126–130 ปอนด์", "130–135 ปอนด์", "135–140 ปอนด์", "140–147 ปอนด์"], "a": 1, "exp": "ตารางรุ่นน้ำหนัก: ไลต์เวท น้ำหนักตั้งแต่ 130 ไม่เกิน 135 ปอนด์", "page": 119}, {"id": "c11q05", "ch": 11, "type": "mc", "q": "ผู้รักษาเวลาต้องให้สัญญาณก่อนเริ่มยกกี่วินาที", "o": ["3 วินาที", "5 วินาที", "10 วินาที", "30 วินาที"], "a": 1, "exp": "ผู้รักษาเวลาให้สัญญาณเริ่มและหมดยกด้วยระฆัง และให้สัญญาณ 5 วินาทีก่อนเริ่มยก", "page": 120}, {"id": "c11q06", "ch": 11, "type": "mc", "q": "ผู้ที่ยอมแพ้แทนนักมวยได้โดยแจ้งผู้ชี้ขาดคือใคร", "o": ["ผู้ให้คะแนน", "หัวหน้าพี่เลี้ยง", "ผู้ประกาศ", "แพทย์สนาม"], "a": 1, "exp": "หัวหน้าพี่เลี้ยงสามารถยอมแพ้แทนนักมวยได้โดยแจ้งผู้ชี้ขาด", "page": 121}, {"id": "c11q07", "ch": 11, "type": "mc", "q": "นักมวยที่แพ้น็อกเอาต์หรือเทคนิคัลน็อกเอาต์ ต้องพักฟื้นอย่างน้อยกี่วัน", "o": ["7 วัน", "14 วัน", "21 วัน", "30 วัน"], "a": 3, "exp": "ระยะพักฟื้นขั้นต่ำ: แพ้น็อกเอาต์หรือเทคนิคัลน็อกเอาต์ 30 วัน", "page": 123}, {"id": "c11q08", "ch": 11, "type": "mc", "q": "นักมวยหญิงแข่งขันกี่ยก ยกละกี่นาที", "o": ["3 ยก ยกละ 3 นาที", "5 ยก ยกละ 2 นาที", "5 ยก ยกละ 3 นาที", "6 ยก ยกละ 2 นาที"], "a": 1, "exp": "ข้อกำหนดนักมวยหญิง: แข่งขัน 5 ยก ยกละ 2 นาที พักระหว่างยก 2 นาที", "page": 124}, {"id": "c11q09", "ch": 11, "type": "tf", "q": "การกระทำถูกแขนหรือขาที่คู่แข่งขันใช้ป้องกัน ถือว่าได้คะแนน", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด การกระทำถูกแขนหรือขาที่คู่แข่งขันใช้ป้องกันเป็นการกระทำที่ไม่ได้คะแนน", "page": 121}, {"id": "c11q10", "ch": 11, "type": "tf", "q": "ผู้ชี้ขาดควรไปถึงสนามก่อนเวลาแข่งขันไม่น้อยกว่า 30 นาที", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก เป็นคำแนะนำในการเตรียมตัวก่อนปฏิบัติหน้าที่ของผู้ชี้ขาด", "page": 125}, {"id": "c12q01", "ch": 12, "type": "mc", "q": "ผู้เรียนที่ทำได้คล่องโดยไม่ต้องคิดและใช้ความสนใจกับสถานการณ์อื่นได้ อยู่ในขั้นใด", "o": ["ขั้นความเข้าใจ (Cognitive)", "ขั้นการฝึกหัด (Associative)", "ขั้นอัตโนมัติ (Autonomous)", "ขั้นเตรียมพร้อม"], "a": 2, "exp": "ขั้นอัตโนมัติ: ทำได้คล่องโดยไม่ต้องคิด ใช้ความสนใจกับสถานการณ์อื่นได้", "page": 127}, {"id": "c12q02", "ch": 12, "type": "mc", "q": "แบบการสอนที่ครูตัดสินใจทั้งหมด ผู้เรียนปฏิบัติตามสัญญาณ คือแบบใด", "o": ["แบบสั่งการ (Command)", "แบบฝึก (Practice)", "แบบตรวจสอบตนเอง (Self-check)", "แบบเลือกระดับ (Inclusion)"], "a": 0, "exp": "แบบสั่งการ (Command) ครูตัดสินใจทั้งหมด ผู้เรียนปฏิบัติตามสัญญาณ", "page": 127}, {"id": "c12q03", "ch": 12, "type": "mc", "q": "แบบการสอนที่มีงานหลายระดับความยาก ให้ผู้เรียนเลือกระดับที่เหมาะกับตนเอง คือแบบใด", "o": ["แบบฝึก (Practice)", "แบบคู่ (Reciprocal)", "แบบเลือกระดับ (Inclusion)", "แบบสั่งการ (Command)"], "a": 2, "exp": "แบบเลือกระดับ (Inclusion) มีงานหลายระดับความยาก ผู้เรียนเลือกระดับที่เหมาะกับตนเอง", "page": 127}, {"id": "c12q04", "ch": 12, "type": "mc", "q": "ผู้ฝึกสอนที่ตัดสินใจและชี้แนะเพียงเล็กน้อย ขาดการจัดการและความรับผิดชอบในการสอน คือผู้ฝึกสอนแบบใด", "o": ["แบบใช้อำนาจ", "แบบยินยอม", "แบบร่วมมือ", "แบบประชาธิปไตย"], "a": 1, "exp": "แบบยินยอม (Submissive Style) ตัดสินใจและชี้แนะเพียงเล็กน้อย ขาดการจัดการและความรับผิดชอบ", "page": 128}, {"id": "c12q05", "ch": 12, "type": "mc", "q": "ผู้ฝึกสอนต้องมีความชำนาญ 2 ด้าน คืออะไร", "o": ["ด้านความรู้ และด้านความสามารถหรือทักษะ", "ด้านร่างกาย และด้านจิตใจ", "ด้านการเงิน และด้านการตลาด", "ด้านภาษา และด้านเทคโนโลยี"], "a": 0, "exp": "ผู้ฝึกสอนต้องมีความชำนาญ 2 ด้าน คือ ด้านความรู้ (Knowledge) และด้านความสามารถหรือทักษะ (Competencies or Skills)", "page": 129}, {"id": "c12q06", "ch": 12, "type": "mc", "q": "ข้อใดเป็นการทดสอบสมรรถภาพทางกายที่ใช้วัดผลในวิชามวยไทยตามเอกสาร", "o": ["ลุกนั่ง 60 วินาที", "วิ่ง 400 เมตรผลัด", "กระโดดค้ำถ่อ", "ว่ายน้ำ 50 เมตร"], "a": 0, "exp": "การทดสอบสมรรถภาพทางกาย เช่น ดัชนีมวลกาย ลุกนั่ง 60 วินาที ดันพื้น 30 วินาที นั่งงอตัว และวิ่งระยะไกล", "page": 131}, {"id": "c12q07", "ch": 12, "type": "mc", "q": "หลักสูตรมวยไทยขั้นพื้นฐานของกรมพลศึกษากำหนดให้ฝึกแม่ไม้กี่ท่า", "o": ["3 ท่า", "5 ท่า", "10 ท่า", "15 ท่า"], "a": 1, "exp": "หลักสูตรขั้นพื้นฐานกำหนดแม่ไม้ 5 ท่า ได้แก่ สลับฟันปลา ปักษาแหวกรัง ชวาซัดหอก อิเหนาแทงกริช และยอเขาพระสุเมรุ", "page": 132}, {"id": "c12q08", "ch": 12, "type": "mc", "q": "การอบอุ่นร่างกายแบ่งเป็น 2 แบบ คืออะไร", "o": ["การอบอุ่นทั่วไป และการอบอุ่นเฉพาะ", "การอบอุ่นแบบหนัก และแบบเบา", "การอบอุ่นในน้ำ และบนบก", "การอบอุ่นเดี่ยว และเป็นคู่"], "a": 0, "exp": "การอบอุ่นร่างกายแบ่งเป็น 2 แบบ คือ การอบอุ่นทั่วไป และการอบอุ่นเฉพาะ", "page": 132}, {"id": "c12q09", "ch": 12, "type": "tf", "q": "ผู้ฝึกสอนต้องรู้ว่าจะสอนอะไร เมื่อไร และอย่างไร", "o": ["ถูก", "ผิด"], "a": 0, "exp": "ถูก ในส่วนของผู้ฝึกสอนต้องรู้ 3 เรื่อง คือ รู้ว่าจะสอนอย่างไร เมื่อไร และควรสอนอะไร", "page": 129}, {"id": "c12q10", "ch": 12, "type": "tf", "q": "การวัดและประเมินผลมวยไทยควรวัดเฉพาะด้านทักษะเท่านั้น", "o": ["ถูก", "ผิด"], "a": 1, "exp": "ผิด ต้องครอบคลุม 3 ด้าน คือ ทักษะพิสัย พุทธิพิสัย และจิตพิสัย", "page": 130}];
